    <script>
        // --- State Management ---
        const state = {
            sessionId: 'session_' + Date.now(),
            messages: [],
            isResearchMode: false,
            isSidebarOpen: false,
            currentFile: null
        };

        // --- Three.js Background Setup ---
        function initThreeJS() {
            const canvas = document.getElementById('canvasBg');
            const renderer = new THREE.WebGLRenderer({ canvas, alpha: false });
            renderer.setSize(window.innerWidth, window.innerHeight);

            window.addEventListener('resize', () => {
                renderer.setSize(window.innerWidth, window.innerHeight);
            });

            // GLSL Shaders from Prompt
            const vertexShader = `
                varying vec2 vUv;
                void main() {
                    vUv = uv;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                }
            `;

            const fragmentShader = `
                uniform float time;
                varying vec2 vUv;

                // Simplex noise simulation
                vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
                vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
                vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }
                float snoise(vec2 v) {
                    const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
                    vec2 i = floor(v + dot(v, C.yy));
                    vec2 x0 = v - i + dot(i, C.xx);
                    vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
                    vec4 x12 = x0.xyxy + C.xxzz;
                    x12.xy -= i1;
                    i = mod289(i);
                    vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 )) + i.x + vec3(0.0, i1.x, 1.0 ));
                    vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
                    m = m*m; m = m*m;
                    vec3 x = 2.0 * fract(p * C.www) - 1.0;
                    vec3 h = abs(x) - 0.5;
                    vec3 ox = floor(x + 0.5);
                    vec3 a0 = x - ox;
                    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0 + h*h);
                    vec3 g;
                    g.x = a0.x * x0.x + h.x * x0.y;
                    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
                    return 130.0 * dot(m, g);
                }

                void main() {
                    float t = time * 0.2;
                    // Adjusted colors for "Deep Space" look matching --bg-deep
                    vec3 c1 = vec3(0.02, 0.02, 0.05); 
                    vec3 c2 = vec3(0.0, 0.05, 0.2);
                    vec3 c3 = vec3(0.0, 0.0, 0.0);
                    vec3 c4 = vec3(0.04, 0.5, 1.0); // Accent shine

                    float n1 = snoise(vUv * 2.0 + vec2(t * 0.5, t * 0.2));
                    float n2 = snoise(vUv * 3.0 - vec2(t * 0.3, t * 0.8));

                    vec3 color = mix(c1, c2, n1);
                    color = mix(color, c3, smoothstep(0.3, 0.8, n2));

                    float lines = sin(vUv.y * 20.0 + n1 * 5.0 + time);
                    color += c4 * 0.03 * smoothstep(0.95, 1.0, lines); // Faint lines

                    gl_FragColor = vec4(color, 1.0);
                }
            `;

            const scene = new THREE.Scene();
            const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
            const uniforms = { time: { value: 0 } };
            const material = new THREE.ShaderMaterial({ vertexShader, fragmentShader, uniforms });
            const plane = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), material);
            scene.add(plane);

            function animate(t) {
                uniforms.time.value = t * 0.001;
                renderer.render(scene, camera);
                requestAnimationFrame(animate);
            }
            animate(0);
        }

