                await uploadFile(state.currentFile);
                state.currentFile = null;
                document.getElementById('attachmentPreview').innerHTML = '';
            }

            state.messages.push({ role: 'user', content: text });

            // Create AI Response Placeholder
            const feed = document.getElementById('chatFeed');
            const aiGroup = document.createElement('div');
            aiGroup.className = 'msg-group ai';
            aiGroup.innerHTML = `<div class="msg-meta">TiffyTime AI</div><div class="msg-bubble"><span class="loading-dots">Gondolkodom</span></div>`;
            feed.appendChild(aiGroup);
            feed.scrollTop = feed.scrollHeight;

            const bubbleContent = aiGroup.querySelector('.msg-bubble');
            let accumulatedResponse = "";

            try {
                const response = await fetch('/api/chat', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        messages: state.messages,
                        session_id: state.sessionId,
                        temperature: 0.7
                    })
                });

                const reader = response.body.getReader();
                const decoder = new TextDecoder();
                bubbleContent.innerHTML = ""; // Clear loading dots

                while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;

                    const chunk = decoder.decode(value);
                    const lines = chunk.split('\n');

                    for (const line of lines) {
                        if (line.startsWith('data: ')) {
                            try {
                                const jsonStr = line.substring(6);
                                if (jsonStr.trim() === '[DONE]') continue;

                                const data = JSON.parse(jsonStr);
                                if (data.content) {
                                    accumulatedResponse += data.content;
                                    // Live update with markdown
                                    bubbleContent.innerHTML = DOMPurify.sanitize(marked.parse(accumulatedResponse));
                                    feed.scrollTop = feed.scrollHeight;
                                }
                            } catch (e) {
                                // Ignore parsing errors for partial chunks
                            }
                        }
                    }
                }

                state.messages.push({ role: 'assistant', content: accumulatedResponse });

            } catch (error) {
                bubbleContent.innerHTML = `<span style="color: #ff4444">Hiba történt: ${error.message}</span>`;
            }
        }

